/**
 * Alert — generated by the React Native Reusables CLI (`alert`), re-skinned to
 * the four severities web's `packages/ui/src/react/alert.tsx` draws.
 *
 * Deviations from upstream:
 * - `variant` is `default | live | warning | destructive`, as on web, and severity
 *   is told apart by fill AND hue so it never rests on colour alone: `default` is
 *   an outlined card, `live`/`warning` fill their `*-subtle` token with ink text,
 *   `destructive` is the outlined card in destructive ink.
 * - `default`, `live` and `warning` sit at `sm` elevation via `useElevation`,
 *   matching web's `shadow-elev-sm`; `destructive` stays flat, as on web. Upstream
 *   draws none.
 * - Spacing uses only `space` steps (`p-4`, `gap-1`), so upstream's `pt-3.5`,
 *   `left-3.5` icon offset and `ml-0.5` are replaced by a row: icon, then text.
 * - `icon` is optional — a short form error reads fine without one.
 * - React 19 idioms: `use` and `<Context value>`, and no extra `RefAttributes` —
 *   `ComponentProps` already carries `ref`, and upstream's second ref type made
 *   every `useRef` passed as `ref` a type error.
 */
import { Icon } from '@/components/ui/icon';
import { Text, TextClassContext } from '@/components/ui/text';
import { cn } from '@/lib/utils';
import { useElevation } from '@/ui/elevation';
import { cva, type VariantProps } from 'class-variance-authority';
import type { LucideIcon } from 'lucide-react-native';
import * as React from 'react';
import { View } from 'react-native';

const alertVariants = cva('w-full flex-row gap-2 rounded-lg border px-4 py-2', {
  variants: {
    variant: {
      default: 'border-border bg-card',
      live: 'border-transparent bg-live-subtle',
      warning: 'border-transparent bg-warning-subtle',
      destructive: 'border-border bg-card',
    },
  },
  defaultVariants: { variant: 'default' },
});

const alertTextVariants = cva('text-sm', {
  variants: {
    variant: {
      default: 'text-card-foreground',
      live: 'text-foreground',
      warning: 'text-foreground',
      destructive: 'text-destructive',
    },
  },
  defaultVariants: { variant: 'default' },
});

type AlertProps = React.ComponentProps<typeof View> &
  VariantProps<typeof alertVariants> & {
    icon?: LucideIcon;
    iconClassName?: string;
  };

function Alert({ className, variant, children, icon, iconClassName, style, ...props }: AlertProps) {
  const lift = useElevation('sm');
  const lifted = variant !== 'destructive';
  return (
    <TextClassContext value={alertTextVariants({ variant })}>
      <View
        role="alert"
        className={cn(alertVariants({ variant }), className)}
        style={[lifted ? lift : null, style]}
        {...props}
      >
        {icon ? (
          <View className="pt-1">
            <Icon as={icon} size={16} className={iconClassName} />
          </View>
        ) : null}
        <View className="flex-1 gap-1">{children}</View>
      </View>
    </TextClassContext>
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<typeof Text>) {
  return <Text className={cn('font-medium', className)} {...props} />;
}

function AlertDescription({ className, ...props }: React.ComponentProps<typeof Text>) {
  return <Text className={cn('leading-5', className)} {...props} />;
}

export { Alert, AlertDescription, AlertTitle };
